using namespace std;

class Solution {
    double fact(int n) {
        double res = 1;
        for (int i = 2; i <= n; ++i) res *= i;
        return res;
    }

    double countArrangements(const vector<int>& counts) {
        int total = 0;
        for (int c : counts) total += c;
        double res = fact(total);
        for (int c : counts) res /= fact(c);
        return res;
    }

public:
    string smallestPalindrome(string s, int k) {
        vector<int> count(26, 0);
        for (char c : s) count[c - 'a']++;
        int oddCount = 0;
        for (int v : count) if (v % 2 == 1) oddCount++;
        if (oddCount > 1) return "";

        vector<int> half(26, 0);
        string mid = "";
        for (int i = 0; i < 26; ++i) {
            half[i] = count[i] / 2;
            if (count[i] % 2 == 1) mid = string(1, 'a' + i);
        }

        if (countArrangements(half) < k) return "";

        int halfLen = 0;
        for (int c : half) halfLen += c;
        string left = "";
        double remK = k;

        for (int step = 0; step < halfLen; ++step) {
            for (int i = 0; i < 26; ++i) {
                if (half[i] == 0) continue;
                half[i]--;
                double arrangements = countArrangements(half);
                if (arrangements >= remK) {
                    left += (char)('a' + i);
                    break;
                } else {
                    remK -= arrangements;
                    half[i]++;
                }
            }
        }
        string rev = left;
        for (int i = 0, j = (int)rev.size() - 1; i < j; ++i, --j) swap(rev[i], rev[j]);
        return left + mid + rev;
    }
};

import java.math.BigInteger;
import java.util.*;

class Solution {
    public String smallestPalindrome(String s, int k) {
        int[] count = new int[26];
        for (char c : s.toCharArray()) count[c - 'a']++;
        int oddCount = 0;
        for (int v : count) if (v % 2 == 1) oddCount++;
        if (oddCount > 1) return "";

        int[] half = new int[26];
        String mid = "";
        for (int i = 0; i < 26; i++) {
            half[i] = count[i] / 2;
            if (count[i] % 2 == 1) mid = String.valueOf((char) ('a' + i));
        }

        BigInteger targetK = BigInteger.valueOf(k);
        if (countArrangements(half).compareTo(targetK) < 0) return "";

        int halfLen = 0;
        for (int c : half) halfLen += c;
        StringBuilder left = new StringBuilder();

        for (int step = 0; step < halfLen; step++) {
            for (int i = 0; i < 26; i++) {
                if (half[i] == 0) continue;
                half[i]--;
                BigInteger arrangements = countArrangements(half);
                if (arrangements.compareTo(targetK) >= 0) {
                    left.append((char) ('a' + i));
                    break;
                } else {
                    targetK = targetK.subtract(arrangements);
                    half[i]++;
                }
            }
        }
        String lStr = left.toString();
        return lStr + mid + left.reverse().toString();
    }

    private BigInteger countArrangements(int[] counts) {
        int total = 0;
        for (int c : counts) total += c;
        BigInteger res = factorial(total);
        for (int c : counts) res = res.divide(factorial(c));
        return res;
    }

    private BigInteger factorial(int n) {
        BigInteger res = BigInteger.ONE;
        for (int i = 2; i <= n; i++) res = res.multiply(BigInteger.valueOf(i));
        return res;
    }
}

var smallestPalindrome = function(s, k) {
    const count = new Array(26).fill(0);
    for (const c of s) count[c.charCodeAt(0) - 97]++;
    let oddCount = 0;
    for (const v of count) if (v % 2 === 1) oddCount++;
    if (oddCount > 1) return "";

    const half = new Array(26).fill(0);
    let mid = "";
    for (let i = 0; i < 26; i++) {
        half[i] = Math.floor(count[i] / 2);
        if (count[i] % 2 === 1) mid = String.fromCharCode(97 + i);
    }

    const fact = n => {
        let res = 1n;
        for (let i = 2n; i <= BigInt(n); i++) res *= i;
        return res;
    };
    const countArrangements = counts => {
        let total = counts.reduce((a, b) => a + b, 0);
        let res = fact(total);
        for (const c of counts) res /= fact(c);
        return res;
    };

    let targetK = BigInt(k);
    if (countArrangements(half) < targetK) return "";

    const halfLen = half.reduce((a, b) => a + b, 0);
    let left = "";
    for (let step = 0; step < halfLen; step++) {
        for (let i = 0; i < 26; i++) {
            if (half[i] === 0) continue;
            half[i]--;
            const arr = countArrangements(half);
            if (arr >= targetK) {
                left += String.fromCharCode(97 + i);
                break;
            } else {
                targetK -= arr;
                half[i]++;
            }
        }
    }
    const rev = left.split("").reverse().join("");
    return left + mid + rev;
};
